// README screenshots (M25): the app on a clean, temporary library holding only
// the demo models generated by scripts/make-demo-models.mjs (this repository's
// own work, MIT) — never a personal library or third-party models.
//
// The demo models have no embedded product images, so a first pass renders
// demo-vase in the app's own 3D viewer and embeds those renders (cover + plate
// image) into a temporary copy; that copy is what the "Images" tab shows.
//
// Run: npm run build && node scripts/readme-screenshots.mjs [en zh-TW zh-CN]
//   -> docs/screenshots/<lang>/*.png
import { _electron as electron } from 'playwright-core';
import JSZip from 'jszip';
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const DEMO = path.join(ROOT, 'demo', 'models');
const OUT = path.join(ROOT, 'docs', 'screenshots');
const LANGS = process.argv.slice(2).length ? process.argv.slice(2) : ['en', 'zh-TW', 'zh-CN'];
const SIZE = { width: 1440, height: 900 };
const MODELS = ['demo-vase', 'demo-knot', 'demo-tower'];

async function launch(base, lang) {
  const env = { ...process.env, MF_USER_DATA: path.join(base, 'userData'), MF_LIBRARY_ROOT: path.join(base, 'library'), MF_LANG: lang };
  const app = await electron.launch({ args: [ROOT], env });
  const page = await app.firstWindow();
  await page.setViewportSize(SIZE);
  await page.waitForSelector('.toolbar');
  return [app, page];
}

const settle = (page, ms = 600) => page.evaluate((t) => new Promise((r) => setTimeout(() => requestAnimationFrame(() => requestAnimationFrame(r)), t)), ms);

async function importFiles(app, page, files) {
  await app.evaluate(({ dialog, Menu }, filePaths) => {
    dialog.showOpenDialog = async () => ({ canceled: false, filePaths });
    Menu.getApplicationMenu().getMenuItemById('import').click();
  }, files);
  // every demo model is our own work: label it self-made so no "unlabelled" banner shows
  for (let i = 0; i < files.length; i++) {
    await page.waitForSelector('[data-testid=import-dialog]');
    await page.click('[data-testid=f-type-self_made]');
    await page.click('[data-testid=import-save]');
    await settle(page, 300);
  }
  await page.waitForSelector('[data-testid=import-dialog]', { state: 'detached' });
}

async function openModel(page, name) {
  await page.fill('[data-testid=search]', name);
  await page.waitForFunction(() => document.querySelectorAll('[data-testid=model-card]').length === 1);
  await page.click('[data-testid=model-card]');
  await page.waitForFunction((n) => document.querySelector('[data-testid=detail-panel] h2')?.textContent === n, name);
  await page.waitForSelector('[data-testid=viewer][data-status=ready]');
  await page.fill('[data-testid=search]', '');
  await settle(page, 1200);
}

/** Pass 1: render demo-vase in the viewer and embed the renders into a copy of it. */
async function vaseWithImages(base) {
  const inbox = path.join(base, 'inbox');
  await fs.mkdir(inbox, { recursive: true });
  const src = path.join(inbox, 'demo-vase.3mf');
  await fs.copyFile(path.join(DEMO, 'demo-vase.3mf'), src);
  const [app, page] = await launch(base, 'en');
  try {
    if (await page.$('[data-testid=settings-done]')) await page.click('[data-testid=settings-done]');
    await importFiles(app, page, [src]);
    await openModel(page, 'demo-vase');
    const viewer = await page.$('[data-testid=viewer-canvas]');
    const modes = '.viewer .modes { visibility: hidden !important; }'; // buttons overlay the canvas
    await page.addStyleTag({ content: modes });
    const render = await viewer.screenshot();
    await page.evaluate(() => document.querySelector('[data-testid=mode-filament]').click()); // a second view for the plate image
    await page.waitForSelector('[data-testid=viewer][data-mode=filament]');
    await settle(page, 800);
    const mapped = await viewer.screenshot();
    const zip = await JSZip.loadAsync(await fs.readFile(path.join(DEMO, 'demo-vase.3mf')));
    zip.file('Auxiliaries/.thumbnails/thumbnail_middle.png', render);
    zip.file('Metadata/plate_1.png', mapped);
    const out = path.join(base, 'demo-vase.3mf');
    await fs.writeFile(out, await zip.generateAsync({ type: 'nodebuffer', compression: 'DEFLATE' }));
    return out;
  } finally {
    await app.close();
  }
}

async function shoot(lang, vase) {
  const base = await fs.mkdtemp(path.join(os.tmpdir(), `mfdeck-shots-${lang}-`));
  const inbox = path.join(base, 'inbox');
  await fs.mkdir(inbox);
  const files = [];
  for (const m of MODELS) {
    const p = path.join(inbox, `${m}.3mf`);
    await fs.copyFile(m === 'demo-vase' ? vase : path.join(DEMO, `${m}.3mf`), p); // import moves files: copy first
    files.push(p);
  }
  const dir = path.join(OUT, lang);
  await fs.mkdir(dir, { recursive: true });
  const shot = async (page, name) => {
    await settle(page);
    await page.screenshot({ path: path.join(dir, `${name}.png`) });
    console.log(`  ${lang}/${name}.png`);
  };
  const [app, page] = await launch(base, lang);
  try {
    if (await page.$('[data-testid=settings-done]')) await page.click('[data-testid=settings-done]');
    await importFiles(app, page, files);
    await page.waitForFunction((n) => document.querySelectorAll('[data-testid=model-card]').length === n, MODELS.length);
    await settle(page, 2500); // thumbnails render in the background

    await openModel(page, 'demo-vase');
    await shot(page, '1-library');

    await page.click('[data-testid=mode-filament]');
    await page.waitForSelector('[data-testid=viewer][data-mode=filament]');
    await page.$eval('[data-testid=detail-panel]', (el) => {
      const a = el.querySelector('[data-testid=color-analysis]') || el.querySelector('.analysis');
      if (a) a.scrollIntoView({ block: 'start' });
    });
    await shot(page, '2-colour-analysis');

    await page.click('[data-testid=mode-original]');
    await page.$eval('[data-testid=detail-panel]', (el) => (el.scrollTop = 0));
    await page.click('[data-testid=preview-mode-images]');
    await page.waitForFunction(() => document.querySelector('[data-testid=embedded-image]')?.naturalWidth > 0);
    await shot(page, '3-embedded-images');
    await page.click('[data-testid=preview-mode-3d]');

    await page.click('[data-testid=suggest-open]');
    await page.waitForSelector('[data-testid=suggest-spools-list]');
    await shot(page, '4-spool-suggestions');
    await page.click('[data-testid=suggest-close]');

    await page.click('[data-testid=purchase-open]');
    await page.waitForSelector('[data-testid=purchase-row]');
    await shot(page, '5-purchase-suggestions');
  } finally {
    await app.close();
    await fs.rm(base, { recursive: true, force: true });
  }
}

const tmp = await fs.mkdtemp(path.join(os.tmpdir(), 'mfdeck-shots-pass1-'));
try {
  const vase = await vaseWithImages(tmp);
  for (const lang of LANGS) await shoot(lang, vase);
} finally {
  await fs.rm(tmp, { recursive: true, force: true });
}
